sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {
    template.print('<table>');
    template.print('<tr><td><b>Equipment:</b></td><td>' + current.equipment.getDisplayValue() + '</td></tr>');
    template.print('<tr><td><b>Quantity:</b></td><td>' + current.getValue('quantity') + '</td></tr>');
    template.print('<tr><td><b>Total cost:</b></td><td>' + current.total_cost.getDisplayValue() + '</td></tr>');
    template.print('</table>');
})(current, template, email, email_action, event);
